// Owner: server-core. POST /dev/seed (ENV=dev + staff bearer only; see requireDev). The body is optional: an empty body or {} loads the data
// embedded at build time in src/seed-data.ts (generated by scripts/gen-seed-data.mjs from data/*.json,
// design/system-prompt-draft.md block A and design/tools-schema.json). scripts/seed_dev.py may post the same
// fields explicitly. Creates a catalog_versions row, services, service_variants, facts, prompt_assets, and
// activates the version when activate != false. Idempotent for the same catalog_version.
import type { Context } from 'hono';
import type { AppEnv, DevSeedRequest, DevSeedResponse, Env } from '../types';
import { TOOL_NAMES } from '../types';
import { HttpError } from '../lib/http';
import { isLocalHost } from '../lib/auth';
import { DEFAULT_CLI_TOOL_NOTE, buildPrompt } from '../lib/prompt';
import { sha256Hex } from '../lib/text';
import { localDate } from '../lib/time';
import { auditStatement } from '../lib/audit';
import { SEED_DATA } from '../seed-data';

interface SourceVariant {
  duration_min: number;
  price_vnd: number;
  time_window?: string | null;
  condition_note?: string | null;
}
interface SourceService {
  id: string;
  group: string;
  name_vi: string;
  display_name_vi?: string;
  short_description_vi?: string | null;
  process_steps_vi?: string[];
  notes_vi?: string | null;
  is_signature?: boolean;
  status?: string;
  variants: SourceVariant[];
}

export async function seedCatalog(env: Env, req: DevSeedRequest, now = Date.now()): Promise<DevSeedResponse> {
  const services = (req.services_json as { services?: SourceService[] })?.services;
  const facts = (req.business_facts_json as { facts?: Record<string, { value?: unknown; status?: string; note?: string }> })?.facts;
  if (!Array.isArray(services) || !services.length) throw new HttpError(422, 'validation_failed', 'services_json.services missing', { field: 'services_json' });
  if (!facts || typeof facts !== 'object') throw new HttpError(422, 'validation_failed', 'business_facts_json.facts missing', { field: 'business_facts_json' });
  if (typeof req.block_a !== 'string' || req.block_a.length < 100) throw new HttpError(422, 'validation_failed', 'block_a missing', { field: 'block_a' });
  const tools = (req.tools_schema_json as { tools?: unknown[] })?.tools;
  // One definition per server tool (TOOL_NAMES: the 7 original tools + attach_menu_images + get_customer_profile).
  if (!Array.isArray(tools) || tools.length !== TOOL_NAMES.length) {
    throw new HttpError(422, 'validation_failed', `tools_schema_json must have ${TOOL_NAMES.length} tools`, { field: 'tools_schema_json' });
  }

  const cv = req.catalog_version ?? `cv_seed_${localDate(now).replaceAll('-', '')}`;
  if (!/^[A-Za-z0-9_.-]{1,64}$/.test(cv)) throw new HttpError(422, 'validation_failed', 'bad catalog_version', { field: 'catalog_version' });
  const activate = req.activate !== false;
  const db = env.DB;
  const existing = await db.prepare('SELECT status FROM catalog_versions WHERE id = ?').bind(cv).first<{ status: string }>();

  const stmts: D1PreparedStatement[] = [
    db.prepare('DELETE FROM service_variants WHERE catalog_version = ?').bind(cv),
    db.prepare('DELETE FROM services WHERE catalog_version = ?').bind(cv),
    db.prepare('DELETE FROM facts WHERE catalog_version = ?').bind(cv),
  ];
  if (!existing) {
    stmts.unshift(
      db.prepare("INSERT INTO catalog_versions (id, status, source_ref, notes, created_by, created_at) VALUES (?, 'draft', ?, ?, 'dev_seed', ?)")
        .bind(cv, 'data/services.json + data/business-facts.json', 'seeded by POST /dev/seed; draft_unapproved data', now),
    );
  }
  let variantCount = 0;
  for (const s of services) {
    stmts.push(
      db.prepare(
        'INSERT INTO services (catalog_version, service_id, group_code, display_name_vi, name_vi, short_description_vi, process_steps_json, notes_vi, is_signature, approval_status, raw_json) VALUES (?,?,?,?,?,?,?,?,?,?,?)',
      ).bind(
        cv,
        s.id,
        s.group,
        s.display_name_vi ?? s.name_vi,
        s.name_vi,
        s.short_description_vi ?? null,
        JSON.stringify(s.process_steps_vi ?? []),
        s.notes_vi ?? null,
        s.is_signature ? 1 : 0,
        s.status ?? 'draft_unapproved',
        JSON.stringify(s),
      ),
    );
    for (const v of s.variants) {
      variantCount++;
      stmts.push(
        db.prepare('INSERT INTO service_variants (catalog_version, service_id, duration_min, time_window, price_vnd, condition_note) VALUES (?,?,?,?,?,?)')
          .bind(cv, s.id, v.duration_min, v.time_window ?? null, v.price_vnd, v.condition_note ?? null),
      );
    }
  }
  for (const [key, f] of Object.entries(facts)) {
    stmts.push(
      db.prepare('INSERT INTO facts (catalog_version, key, value_json, status, note) VALUES (?,?,?,?,?)').bind(
        cv,
        key,
        f.value === undefined || f.value === null ? null : JSON.stringify(f.value),
        f.status ?? 'missing',
        f.note ?? null,
      ),
    );
  }
  const note = req.cli_tool_note ?? DEFAULT_CLI_TOOL_NOTE;
  const toolsBody = JSON.stringify(req.tools_schema_json);
  for (const [key, body] of [
    ['block_a', req.block_a],
    ['tools_schema', toolsBody],
    ['cli_tool_note', note],
  ] as const) {
    stmts.push(
      db.prepare(
        'INSERT INTO prompt_assets (key, body, sha256, updated_at) VALUES (?,?,?,?) ON CONFLICT(key) DO UPDATE SET body = excluded.body, sha256 = excluded.sha256, updated_at = excluded.updated_at',
      ).bind(key, body, await sha256Hex(body), now),
    );
  }
  if (activate) {
    stmts.push(
      db.prepare("UPDATE catalog_versions SET status = 'retired' WHERE status = 'active' AND id != ?").bind(cv),
      db.prepare("UPDATE catalog_versions SET status = 'active', activated_at = ?, approved_by = COALESCE(approved_by, 'dev_seed') WHERE id = ?").bind(now, cv),
    );
  }
  stmts.push(auditStatement(env, { actor_type: 'system', actor_id: 'dev_seed', action: 'catalog.seed', entity: 'catalog_version', entity_id: cv, after: { activate } }, now));
  await db.batch(stmts);

  const prompt = await buildPrompt(env, cv);
  return { catalog_version: cv, services: services.length, variants: variantCount, facts: Object.keys(facts).length, prompt_hash: prompt.prompt_hash };
}

export async function seed(c: Context<AppEnv>): Promise<Response> {
  const raw = await c.req.text();
  let body: Partial<DevSeedRequest> = {};
  if (raw.trim()) {
    try {
      body = JSON.parse(raw) as Partial<DevSeedRequest>;
    } catch {
      throw new HttpError(400, 'bad_request', 'body must be JSON');
    }
  }
  // Prompt and catalog overrides from the body are accepted only on a local host; elsewhere only the
  // build-time copy (src/seed-data.ts) can be activated.
  const overrides = body.services_json !== undefined || body.business_facts_json !== undefined || body.block_a !== undefined || body.tools_schema_json !== undefined || body.cli_tool_note !== undefined;
  if (overrides && !isLocalHost(c.req.url)) {
    throw new HttpError(403, 'forbidden', 'catalog / prompt overrides are accepted only on a local host; post {} to load the build-time copy');
  }
  const req: DevSeedRequest = {
    services_json: body.services_json ?? SEED_DATA.services_json,
    business_facts_json: body.business_facts_json ?? SEED_DATA.business_facts_json,
    block_a: body.block_a ?? SEED_DATA.block_a,
    tools_schema_json: body.tools_schema_json ?? SEED_DATA.tools_schema_json,
    ...(body.cli_tool_note !== undefined ? { cli_tool_note: body.cli_tool_note } : {}),
    ...(body.catalog_version !== undefined ? { catalog_version: body.catalog_version } : {}),
    ...(body.activate !== undefined ? { activate: body.activate } : {}),
  };
  return c.json(await seedCatalog(c.env, req));
}

/** POST /staff/catalog/load-embedded (staff token): activates the build-time copy (src/seed-data.ts) on any host,
 * including production. No body overrides are accepted, so a staff token cannot inject prompt or prices. */
export async function loadEmbeddedCatalog(c: Context<AppEnv>): Promise<Response> {
  const req: DevSeedRequest = {
    services_json: SEED_DATA.services_json,
    business_facts_json: SEED_DATA.business_facts_json,
    block_a: SEED_DATA.block_a,
    tools_schema_json: SEED_DATA.tools_schema_json,
  };
  return c.json(await seedCatalog(c.env, req));
}
